// Validate and normalize a travel-directory submission. Nothing here makes the business
// "trusted": it only rejects malformed intake and prepares a conservative standard listing.
const SETTINGS = {
  reviewTo: 'augustministry@gmail.com',
  site: 'https://www.ghananice.com',
  sheetId: '1Af866rDXLZ1mnnHHVvqQ63HL9cs9CYYab2a6JBsdMq0',
  branch: 'main'
};
const CATEGORIES = {
  tours: 'Tours & guides',
  transport: 'Getting around',
  stay: 'Places to stay'
};
const REGIONS = {
  'greater-accra': 'Greater Accra', central: 'Central', volta: 'Volta', savannah: 'Savannah', western: 'Western',
  ashanti: 'Ashanti', eastern: 'Eastern', northern: 'Northern', 'upper-east': 'Upper East', 'upper-west': 'Upper West',
  'north-east': 'North East', oti: 'Oti', bono: 'Bono', 'bono-east': 'Bono East', ahafo: 'Ahafo', 'western-north': 'Western North'
};

const input = $input.first();
const raw = input.json.body && typeof input.json.body === 'object' ? input.json.body : input.json;
const text = (value, max) => String(value ?? '').replace(/\s+/g, ' ').trim().slice(0, max);
if (text(raw.companyFax, 100)) return [{ json: { verdict: 'drop', reason: 'honeypot' } }];

const email = text(raw.email, 180).toLowerCase();
let website = text(raw.website, 500);
try {
  const parsed = new URL(website);
  const privateHost = /^(localhost|127\.|10\.|192\.168\.|172\.(1[6-9]|2\d|3[01])\.)/i.test(parsed.hostname);
  website = parsed.protocol === 'https:' && !privateHost ? parsed.href : '';
} catch { website = ''; }

const businessName = text(raw.businessName, 100);
const category = CATEGORIES[raw.category] ? raw.category : '';
const primaryRegion = REGIONS[raw.primaryRegion] ? raw.primaryRegion : '';
const listingType = raw.listingType === 'featured' ? 'featured' : 'standard';
const idSeed = /^[0-9a-f-]{16,64}$/i.test(raw.id || '') ? raw.id.toLowerCase() : `${Date.now()}-${$execution.id}`;
const slug = businessName.toLowerCase().normalize('NFKD').replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '').slice(0, 54) || 'service';
const listingId = `${slug}-${idSeed.replace(/[^a-z0-9]/g, '').slice(0, 8)}`;
const submittedAt = /^\d{4}-\d\d-\d\dT/.test(raw.submittedAt || '') ? raw.submittedAt : new Date().toISOString();

const service = {
  id: idSeed,
  listingId,
  submittedAt,
  businessName,
  category,
  categoryLabel: CATEGORIES[category] || '',
  primaryRegion,
  regionName: REGIONS[primaryRegion] || '',
  baseLocation: text(raw.baseLocation, 100),
  coverage: text(raw.coverage, 180),
  description: text(raw.description, 600),
  website,
  listingType,
  featuredInterest: listingType === 'featured',
  contactName: text(raw.contactName, 100),
  email: /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(email) ? email : '',
  phone: text(raw.phone, 40),
  consent: raw.consent === true,
  source: text(raw.source, 60),
  pageUrl: text(raw.pageUrl, 400)
};

let reason = '';
if (service.businessName.length < 2) reason = 'A business name is required.';
else if (!service.category) reason = 'Choose a supported service category.';
else if (!service.primaryRegion) reason = 'Choose the primary region.';
else if (service.baseLocation.length < 2) reason = 'A base location is required.';
else if (!service.website) reason = 'A public HTTPS website or social media page is required.';
else if (service.coverage.length < 2) reason = 'Service coverage is required.';
else if (service.description.length < 30) reason = 'The description is too short.';
else if (service.contactName.length < 2) reason = 'A contact name is required.';
else if (!service.email) reason = 'A valid email is required.';
else if (!service.consent) reason = 'The representative confirmation is required.';
if (reason) return [{ json: { verdict: 'invalid', reason } }];

const checked = new Intl.DateTimeFormat('en-GB', { day: '2-digit', month: 'short', year: 'numeric', timeZone: 'Africa/Accra' }).format(new Date()).replace(',', '');
const listing = {
  id: listingId,
  name: service.businessName,
  category: service.category,
  categoryLabel: service.categoryLabel,
  base: service.baseLocation,
  regions: [service.primaryRegion],
  coverage: service.coverage,
  description: service.description,
  goodFor: [],
  website: service.website,
  checked,
  featured: false
};

const now = new Date().toISOString();
const row = [service.id, service.submittedAt, 'received', service.businessName, service.category, service.primaryRegion,
  service.baseLocation, service.coverage, service.description, service.website, service.contactName, service.email,
  service.phone, service.listingType, '', '', service.source, now, '', '', service.listingId];

return [{ json: { verdict: 'ok', service, listing, settings: SETTINGS, row } }];

// Prepare the owner approval and submitter emails, including a duplicate warning from the
// currently published service-submissions file. Approval publishes a standard listing only;
// a featured upgrade still requires a personal pricing, duration and media-rights agreement.
const read = $('Read service').first().json;
const { service, listing, settings } = read;
let published = [];
try {
  const encoded = $('Current published services').first().json.content || '';
  published = JSON.parse(Buffer.from(encoded, 'base64').toString('utf8')).services || [];
} catch { published = []; }

// Two businesses can share instagram.com or facebook.com, so a social page is identified by
// its host and page name; an ordinary website is identified by its host alone.
const SOCIAL_HOSTS = ['instagram.com', 'facebook.com', 'fb.com', 'tiktok.com', 'x.com', 'twitter.com', 'youtube.com', 'linktr.ee', 'wa.me'];
const linkKey = value => {
  try {
    const url = new URL(value);
    const host = url.hostname.replace(/^(www|m|web)\./, '').toLowerCase();
    if (!SOCIAL_HOSTS.includes(host)) return host;
    return `${host}/${url.pathname.replace(/^\/+|\/+$/g, '').toLowerCase()}`;
  } catch { return ''; }
};
const duplicate = published.find(item => item.name?.toLowerCase() === listing.name.toLowerCase() || (linkKey(item.website) && linkKey(item.website) === linkKey(listing.website)));
const firstName = service.contactName.split(/\s+/)[0] || '';
const esc = value => String(value ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const link = value => `<a href="${esc(value)}">${esc(value)}</a>`;
const wrap = body => `<div style="font-family:Georgia,serif;font-size:16px;line-height:1.55;color:#11110f;max-width:560px">${body}<p style="margin-top:28px">August<br><span style="font-family:Arial,sans-serif;font-size:12px;color:#666">GhanaNice · <a href="${settings.site}">ghananice.com</a></span></p></div>`;
const featuredNote = service.featuredInterest
  ? 'They are interested in featured placement. Contact them personally to agree pricing, duration and image permissions. Approving here publishes the standard listing; the featured upgrade remains manual.'
  : 'They requested a standard listing.';
const duplicateNote = duplicate ? `Possible duplicate: “${duplicate.name}” is already published at ${duplicate.website}.` : 'No matching name or link is already in the submitted-services file.';

const approvalText = [
  `${service.businessName} — ${service.categoryLabel}`,
  `${service.baseLocation}, ${service.regionName}`,
  service.description,
  `Coverage: ${service.coverage}`,
  `Link (website or social page): ${service.website}`,
  `Contact: ${service.contactName} · ${service.email}${service.phone ? ' · ' + service.phone : ''}`,
  featuredNote,
  duplicateNote,
  'Before approving, confirm the website or social page belongs to the business, the service is relevant to travel in Ghana, the location/category/claims match its public information, and the representative can be contacted. Approval publishes only the standard listing.'
].join('\n\n');

const hello = firstName ? `Hi ${esc(firstName)},` : 'Hello,';
const thanksHtml = wrap(`<p>${hello}</p><p>Thank you for submitting <b>${esc(service.businessName)}</b> to the GhanaNice travel directory. We’ll check the business, its website or social media page and the details you supplied before anything is published.</p>${service.featuredInterest ? '<p>You also expressed interest in featured placement. I’ll contact you personally about pricing, duration and suitable images; selecting it on the form does not commit you to anything.</p>' : ''}<p>We’ll email you after the review.</p>`);
const liveUrl = `${settings.site}/travel-directory.html?business=${encodeURIComponent(listing.id)}#service-${encodeURIComponent(listing.id)}`;
const liveHtml = wrap(`<p>${hello}</p><p><b>${esc(service.businessName)}</b> is now listed in the GhanaNice travel directory.</p><p><a href="${liveUrl}">View the listing</a></p>${service.featuredInterest ? '<p>Your standard listing is live. I’ll follow up separately about the optional featured placement.</p>' : ''}`);
const rejectedHtml = wrap(`<p>${hello}</p><p>Thank you for submitting <b>${esc(service.businessName)}</b>. We couldn’t add it to the GhanaNice directory after reviewing the public information supplied.</p><p>You can reply with an updated website or social media page, or corrected details, if something has changed.</p>`);

const range = $('Log received').first().json.updates?.updatedRange || '';
const rowNumber = Number((range.match(/![A-Z]+(\d+)/) || [])[1]) || null;
const checks = duplicate ? `possible duplicate: ${duplicate.name}` : 'manual checks pending';
const now = new Date().toISOString();
const row = [...read.row];
row[2] = service.featuredInterest ? 'featured interest: waiting for review' : 'waiting for review';
row[14] = checks;
row[17] = now;

return [{ json: {
  service, listing, settings, row, rowNumber, approvalText, thanksHtml, liveHtml, rejectedHtml,
  email: service.email,
  subjectThanks: `We received ${service.businessName} for GhanaNice`,
  subjectApproval: `${service.featuredInterest ? '[Featured interest] ' : ''}Approve “${service.businessName}” for GhanaNice?`,
  subjectLive: `${service.businessName} is on GhanaNice`,
  subjectRejected: `About your GhanaNice directory submission`,
  liveUrl
} }];

// Add the approved standard listing to the JSON file read by the directory. Re-read the file
// after the approval wait so concurrent approvals cannot overwrite one another.
const review = $('Prepare review').first().json;
const current = $input.first().json;
let body = { services: [] };
try { body = JSON.parse(Buffer.from(current.content || '', 'base64').toString('utf8')); } catch { body = { services: [] }; }
if (!Array.isArray(body.services)) body.services = [];

// Two businesses can share instagram.com or facebook.com, so a social page is identified by
// its host and page name; an ordinary website is identified by its host alone.
const SOCIAL_HOSTS = ['instagram.com', 'facebook.com', 'fb.com', 'tiktok.com', 'x.com', 'twitter.com', 'youtube.com', 'linktr.ee', 'wa.me'];
const linkKey = value => {
  try {
    const url = new URL(value);
    const host = url.hostname.replace(/^(www|m|web)\./, '').toLowerCase();
    if (!SOCIAL_HOSTS.includes(host)) return host;
    return `${host}/${url.pathname.replace(/^\/+|\/+$/g, '').toLowerCase()}`;
  } catch { return ''; }
};
const exists = body.services.some(item => item.id === review.listing.id || (linkKey(item.website) && linkKey(item.website) === linkKey(review.listing.website)));
if (!exists) body.services.push(review.listing);
body.updatedAt = new Date().toISOString();

return [{ json: {
  path: 'dist/data/service-submissions.json',
  content: Buffer.from(JSON.stringify(body, null, 2) + '\n').toString('base64'),
  baseTree: $('Git commit').first().json.tree.sha,
  head: $('Git ref').first().json.object.sha,
  alreadyPublished: exists,
  message: `Add travel service: ${review.listing.name}\n\nApproved through the GhanaNice service intake.`
} }];
